import { ErrorSummary } from '@absoluteui/components/error-summary';
import { TextInput } from '@absoluteui/components/text-input';

const summaryHost = document.createElement('div');
const nameHost = document.createElement('div');
document.body.append(summaryHost, nameHost);
const name = TextInput.create(nameHost, { label: 'Full name' }).input;
const summary = ErrorSummary.create(summaryHost);
// Focus moves to the summary; each linked item focuses its target on activation.
summary.show([
  { message: 'Enter your full name', target: name },
  { message: 'The service is busy. Try again in a few minutes.' },
]);

import { ErrorSummary, type ErrorSummaryNavigateDetail } from '@absoluteui/components/error-summary';
import { TextInput } from '@absoluteui/components/text-input';

const summaryHost = document.createElement('div');
const emailHost = document.createElement('div');
document.body.append(summaryHost, emailHost);
const email = TextInput.create(emailHost, { label: 'Email', name: 'email', type: 'email', required: true });
const summary = ErrorSummary.create(summaryHost, { headingLevel: 3, description: 'Fix the following to continue.' });

if (!email.reportValidity()) {
  summary.show([{ message: email.validity.message, target: email.host, focus: () => { email.focus(); } }]);
}
summaryHost.addEventListener('aui-navigate', (event) => {
  const { index } = (event as CustomEvent<ErrorSummaryNavigateDetail>).detail;
  summaryHost.dataset.lastNavigated = String(index);
});

import { configureAbsoluteUI } from '@absoluteui/core';
import '@absoluteui/components/error-summary';

configureAbsoluteUI({ components: { errorSummary: { headingLevel: 3 } } });
